#!/usr/bin/env python3
"""__DISPLAY_NAME__ — generated by `plexi app init`.

=== PLEXI SDK QUICK REFERENCE (for coding agents) ===

Two rendering modes (never use both):
  1. view(self) -> Component    — declarative UI tree (forms, lists, dashboards)
  2. on_render(self, ctx)       — pixel-level canvas (games, visualizations, animation)

DECLARATIVE MODE (view):
  from plexi_sdk.ui import Column, AppBar, Label, Spacer, FooterKeys, Section,
                           SelectList, TextInput, Divider, Card, Heading, ButtonRow
  def view(self):
      return Column([AppBar("Title"), Label("text"), Spacer(grow=True), FooterKeys([...])])

CANVAS MODE (on_render) — for games/graphics:
  def on_render(self, ctx):
      ctx.rect(x, y, w, h, color)           # filled rectangle
      ctx.text(x, y, string, size=14.0, color="#cdd6f4")  # text at position
      ctx.circle(cx, cy, radius, color)      # filled circle
      ctx.line(x1, y1, x2, y2, color, thickness=1.0)
  Use self.w, self.h for pane dimensions. Use ctx.elapsed for frame delta time.
  Call self.emit.schedule_render(after_ms=16) for animation loops (~60fps).
  Enable mouse: self.emit.set_mouse_tracking(True) in on_init.

LIFECYCLE HOOKS:
  on_init(self)                — setup (called once after handshake)
  on_key(self, key, mods)      — key: "a"-"z", "up/down/left/right", "space",
                                 "return", "escape", "plus", "minus", "f1"-"f12"
                                 mods: {"shift": bool, "ctrl": bool, "alt": bool, "meta": bool}
  on_click(self, x, y, button) — requires set_mouse_tracking(True)
  on_escape(self) -> bool      — return True if handled, False to let host close
  on_path_changed(self, cwd)   — workspace directory changed
  on_shutdown(self)            — cleanup before close

STATE & I/O:
  self.state.get("key", default) / self.state.save({"key": val})  — persisted across restarts
  self.emit.schedule_render(after_ms=16)   — request next frame
  self.emit.notify(title, priority, body)  — fire notification
  self.emit.info/warn/error(msg)           — structured logging
  await self.emit.http_get(url)            — HTTP (needs net.http capability)
  await self.emit.ai_query(tier, sys, msgs)— LLM call (needs ai.query capability)

REACTIVE STATE (auto re-renders on assignment):
  from plexi_sdk import App, State
  class MyApp(App):
      count = State(0)  # assigning self.count = 5 auto-triggers re-render

PANE DIMENSIONS: self.w, self.h — logical pixels, updated each frame.
"""
from plexi_sdk import App
from plexi_sdk.ui import AppBar, Column, FooterKeys, Label, Spacer


class __CLASS_NAME__(App):
    def on_init(self) -> None:
        self.count: int = self.state.get("count", 0)

    def view(self):
        return Column([
            AppBar(title="__DISPLAY_NAME__"),
            Label(str(self.count), bold=True),
            Spacer(grow=True),
            FooterKeys(shortcuts=[
                ("+", "increment"),
                ("-", "decrement"),
                ("r", "reset"),
            ]),
        ])

    def on_key(self, key: str, mods: dict) -> None:
        if key in ("equals", "plus"):
            self.count += 1
        elif key == "minus":
            self.count -= 1
        elif key == "r":
            self.count = 0
        self.state.save({"count": self.count})
        self.emit.schedule_render()


__CLASS_NAME__().run()
